// Canvas item shader (2D dissolve effect)
shader_type canvas_item;

uniform float dissolve_amount : hint_range(0, 1) = 0.0;
uniform sampler2D noise_tex : source_color;

void fragment() {
    vec4 tex = texture(TEXTURE, UV);
    float noise = texture(noise_tex, UV).r;
    float cutoff = noise - dissolve_amount;
    COLOR = tex;
    if (cutoff < 0.0) discard;
    COLOR.a = smoothstep(-0.1, 0.0, cutoff);
}

// Spatial shader (3D outline)
shader_type spatial;

uniform float outline_width : hint_range(0, 0.1) = 0.02;
uniform vec4 outline_color : source_color = vec4(1.0, 0.0, 0.0, 1.0);

void fragment() {
    ALBEDO = vec3(0.8, 0.2, 0.2);
    METALLIC = 0.3;
    ROUGHNESS = 0.4;
}

void vertex() {
    VERTEX += NORMAL * outline_width;
}

Input Map & Actions:
extends CharacterBody2D

func _input(event: InputEvent) -> void:
    # Event-driven (use for UI/interaction)
    if event.is_action_pressed("interact"):
        open_chest()

    if event is InputEventMouseButton:
        if event.button_index == MOUSE_BUTTON_LEFT:
            shoot_at(event.position)

    if event is InputEventMouseMotion:
        if event.button_mask & MOUSE_BUTTON_MASK_RIGHT:
            camera_pan(event.relative)

func _process(delta: float) -> void:
    # Polling (use for continuous movement)
    var move = Input.get_vector("move_left", "move_right", "move_up", "move_down")
    var sprint = Input.get_action_strength("sprint")  # analog: 0.0-1.0
    velocity = move * speed * (1.0 + sprint * 0.5)
    move_and_slide()

func _unhandled_input(event: InputEvent) -> void:
    # Fallback for unhandled events (e.g. UI consumes first)
    if event.is_action_pressed("ui_cancel"):
        pause_game()

AnimationPlayer & AnimationTree:
extends CharacterBody3D

@onready var anim_player := $AnimationPlayer
@onready var anim_tree := $AnimationTree
@onready var state_machine := anim_tree.get("parameters/playback") as AnimationNodeStateMachinePlayback

func _physics_process(delta: float) -> void:
    var speed := Input.get_axis("backward", "forward")
    var direction := Input.get_axis("left", "right")

    # Drive blend space parameters
    anim_tree.set("parameters/move/blend_position", speed)
    anim_tree.set("parameters/turn/blend_position", direction)

    # State machine transitions
    if speed > 0.1:
        state_machine.travel("move")
    elif direction < -0.1 or direction > 0.1:
        state_machine.travel("turn")
    else:
        state_machine.travel("idle")

    # One-shot animation
    if Input.is_action_just_pressed("attack"):
        state_machine.travel("attack")
        # Queue return to locomotion after attack
        await anim_player.animation_finished
        state_machine.travel("idle")

